CREATE MATERIALIZED VIEW gold.per_minute_metrics_mv TO gold.per_minute_metrics (`minute_bucket` DateTime('UTC'), `platform` LowCardinality(String), `video_resolution` LowCardinality(String), `country` LowCardinality(String), `audio_languages` AggregateFunction(groupUniqArray, String), `subtitle_languages` AggregateFunction(groupUniqArray, String), `category` LowCardinality(String), `show_name` LowCardinality(String), `title` LowCardinality(String), `active_users_state` AggregateFunction(uniqExact, FixedString(64)), `active_session_state` AggregateFunction(uniqExact, FixedString(64))) AS SELECT minute_bucket, platform, video_resolution, country, groupUniqArrayMergeState(audio_languages) AS audio_languages, groupUniqArrayMergeState(subtitle_languages) AS subtitle_languages, finalizeAggregation(category) AS category, finalizeAggregation(show_name) AS show_name, finalizeAggregation(title) AS title, uniqExactStateIf(user_id, finalizeAggregation(is_active) = 1) AS active_users_state, uniqExactStateIf(video_session_id, finalizeAggregation(is_active) = 1) AS active_session_state FROM silver.session_minute_state GROUP BY minute_bucket, platform, video_resolution, country, category, show_name, title